import{_ as d,o as a,c as r,a2 as e}from"./chunks/framework.CqpfiAoK.js";const u=JSON.parse('{"title":"যুগ বিভাজন সারি সারণি","description":"","frontmatter":{},"headers":[],"relativePath":"bn/0070-纪元划分总表.md","filePath":"bn/0070-纪元划分总表.md"}'),l={name:"bn/0070-纪元划分总表.md"};function i(h,t,o,n,s,_){return a(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="যুগ-বিভাজন-সারি-সারণি" tabindex="-1">যুগ বিভাজন সারি সারণি <a class="header-anchor" href="#যুগ-বিভাজন-সারি-সারণি" aria-label="Permalink to &quot;যুগ বিভাজন সারি সারণি&quot;">​</a></h1><table tabindex="0"><thead><tr><th>আইটেম</th><th>বিষয়বস্তু</th></tr></thead><tbody><tr><td>নথি নম্বর</td><td>70</td></tr><tr><td>মডিউল</td><td>ঐতিহাসিক যুগ ও গুরুত্বপূর্ণ ঘটনা</td></tr><tr><td>মূল কীওয়ার্ড</td><td>যুগ বিভাজন, ঐতিহাসিক পর্যায়বিভাগ, চার-পর্যায় মাত্রা-বৃদ্ধি, সময়রেখা, মাইলফলক</td></tr></tbody></table><h2 id="_1-যুগ-বিভাজনের-মূল-নীতি" tabindex="-1">1. যুগ বিভাজনের মূল নীতি <a class="header-anchor" href="#_1-যুগ-বিভাজনের-মূল-নীতি" aria-label="Permalink to &quot;1. যুগ বিভাজনের মূল নীতি&quot;">​</a></h2><p>হেংইয়ান-ঝৌর ঐতিহাসিক যুগ বিভাজন চার-পর্যায় মাত্রা-বৃদ্ধি পথকে মূল কাঠামো হিসেবে গ্রহণ করে, এবং অ্যাঙ্কর প্রক্রিয়ার বিকাশের অবস্থাকে মূল পর্যায়বিভাগের ভিত্তি হিসেবে গ্রহণ করে। প্রতিটি যুগ মহান সভ্যতা এবং মহাবিশ্বের সম্পর্কের একটি মৌলিক পরিবর্তনের সাথে সম্পর্কিত, যুগগুলির মধ্যে সীমানা স্বেচ্ছাচারী সময়ের বিন্দু নয়, বরং মহাবিশ্ব-স্তরের অর্থবহ গুরুত্বপূর্ণ ঘটনা দ্বারা চিহ্নিত করা হয়।</p><p>যুগ বিভাজন তিনটি নীতি অনুসরণ করে:</p><ul><li><strong>মাত্রা-বৃদ্ধি মিল নীতি</strong>: প্রতিটি বড় যুগ চার-পর্যায় মাত্রা-বৃদ্ধি পথের একটি পর্যায়ের সাথে সম্পর্কিত, যুগের ভেতরের সূক্ষ্ম পর্যায়গুলি সেই পর্যায়ের মূল অগ্রগতির সাথে সম্পর্কিত</li><li><strong>ঘটনা চিহ্নিতকরণ নীতি</strong>: যুগের শুরু এবং শেষের বিন্দু চিহ্নিতকারী গুরুত্বপূর্ণ ঘটনা দ্বারা নির্ধারিত হয়, সহজ সময় সমান বিভাজন দ্বারা নয়</li><li><strong>সভ্যতা অবস্থা নীতি</strong>: প্রতিটি যুগ সেই সময়ের সভ্যতার মূল বৈশিষ্ট্য দ্বারা নামকরণ করা হয়, যা তখনকার মূল দ্বন্দ্ব এবং বিকাশের দিককে প্রতিফলিত করে</li></ul><h2 id="_2-হেংইয়ান-ঝৌর-ঐতিহাসিক-যুগ-সারি-সারণি" tabindex="-1">2. হেংইয়ান-ঝৌর ঐতিহাসিক যুগ সারি সারণি <a class="header-anchor" href="#_2-হেংইয়ান-ঝৌর-ঐতিহাসিক-যুগ-সারি-সারণি" aria-label="Permalink to &quot;2. হেংইয়ান-ঝৌর ঐতিহাসিক যুগ সারি সারণি&quot;">​</a></h2><table tabindex="0"><thead><tr><th>যুগ নম্বর</th><th>যুগের নাম</th><th>সম্পর্কিত মাত্রা-বৃদ্ধি পর্যায়</th><th>শুরু-শেষ চিহ্নিতকারী ঘটনা</th><th>মূল বৈশিষ্ট্য</th></tr></thead><tbody><tr><td>প্রথম যুগ</td><td>প্রি-অ্যাঙ্কর যুগ</td><td>মাত্রা-বৃদ্ধির আগে</td><td>মহাবিশ্বের জন্ম→প্রথম প্রজন্মের অ্যাঙ্কর জাগরণ</td><td>লুণ্ঠনমূলক সাধনা প্রাধান্য, সভ্যতার বিচ্ছিন্নতা ঘন ঘন</td></tr><tr><td>দ্বিতীয় যুগ</td><td>অ্যাঙ্কর জাগরণ যুগ</td><td>বাস্তব ভিত্তি নির্মাণ শুরু</td><td>প্রথম প্রজন্মের অ্যাঙ্কর জাগরণ→সিম্বায়োসিস চার্টার স্বাক্ষর</td><td>অ্যাঙ্কর প্রক্রিয়া প্রতিষ্ঠিত, লুণ্ঠন-বিরোধী চিন্তার অঙ্কুর</td></tr><tr><td>তৃতীয় যুগ</td><td>সিম্বায়োসিস ব্যবস্থা প্রতিষ্ঠা কাল</td><td>বাস্তব ভিত্তি নির্মাণ</td><td>সিম্বায়োসিস চার্টার স্বাক্ষর→তিনশট সিস্টেম সম্পূর্ণরূপে খোলা</td><td>সিম্বায়োসিস ব্যবস্থা প্রয়োগ করা হয়, সামাজিক পুনর্গঠন সম্পন্ন</td></tr><tr><td>চতুর্থ যুগ</td><td>সিস্টেম খোলা এবং সক্রিয়করণ যুগ</td><td>প্রযুক্তি ক্ষমতায়ন শুরু</td><td>তিনশট সিস্টেম খোলা→20% সক্রিয়করণ কৌশল সম্পন্ন</td><td>সাধনা জনপ্রিয়করণ, নিয়ম প্রকৌশল প্রযুক্তির ব্রেকথ্রু</td></tr><tr><td>পঞ্চম যুগ</td><td>প্রথম মাত্রা-বৃদ্ধি যুগ</td><td>প্রযুক্তি ক্ষমতায়ন→চেতনা বিবর্তন</td><td>প্রথম মাত্রা-বৃদ্ধি সফল→সর্ব-জাতি গণতন্ত্র প্রতিষ্ঠা</td><td>সভ্যতার মাত্রা-বৃদ্ধি যাচাই, চেতনা ডোমেইন ইন্টারফেস ব্রেকথ্রু</td></tr><tr><td>ষষ্ঠ যুগ</td><td>সর্ব-জাতি গণতন্ত্র যুগ</td><td>চেতনা বিবর্তন</td><td>সর্ব-জাতি গণতন্ত্র প্রতিষ্ঠা→আন্তঃ-তল অনুসন্ধান শুরু</td><td>সর্ব-জাতি ব্যবস্থা একীভূত, সমষ্টিগত চেতনা সিম্বায়োসিস</td></tr><tr><td>সপ্তম যুগ</td><td>আন্তঃ-তল অনুসন্ধান যুগ</td><td>চেতনা বিবর্তন→আন্তঃগ্রহীয় সিম্বায়োসিস</td><td>আন্তঃ-তল অনুসন্ধান শুরু→আন্তঃগ্রহীয় নেটওয়ার্ক প্রাথমিকভাবে নির্মিত</td><td>তলের বড় আবিষ্কার, অ্যাঙ্কর নেটওয়ার্ক সম্প্রসারণ</td></tr><tr><td>অষ্টম যুগ</td><td>আন্তঃগ্রহীয় সিম্বায়োসিস যুগ</td><td>আন্তঃগ্রহীয় সিম্বায়োসিস</td><td>আন্তঃগ্রহীয় নেটওয়ার্ক নির্মিত→মহাবিশ্বের সামগ্রিক মাত্রা-বৃদ্ধি</td><td>সর্ব-জাতি মহাবিশ্ব সিম্বায়োসিস, মহাবিশ্বের মাত্রা-বৃদ্ধি চলমান</td></tr></tbody></table><h2 id="_3-প্রতিটি-যুগের-সময়কাল-এবং-মূল-সূচক" tabindex="-1">3. প্রতিটি যুগের সময়কাল এবং মূল সূচক <a class="header-anchor" href="#_3-প্রতিটি-যুগের-সময়কাল-এবং-মূল-সূচক" aria-label="Permalink to &quot;3. প্রতিটি যুগের সময়কাল এবং মূল সূচক&quot;">​</a></h2><p>যেহেতু হেংইয়ান-ঝৌ একাধিক তল অন্তর্ভুক্ত করে, বিভিন্ন তলে সময়ের প্রবাহ ভিন্ন, যুগের সময়কাল মূল তলের মানক সময়কে ভিত্তি করে:</p><table tabindex="0"><thead><tr><th>যুগ</th><th>আনুমানিক সময়কাল</th><th>অ্যাঙ্কর কভারেজ রেট</th><th>সাধকের অনুপাত</th><th>সিম্বায়োসিস ডিগ্রি সূচক</th></tr></thead><tbody><tr><td>প্রি-অ্যাঙ্কর যুগ</td><td>অজানা (কয়েক বিলিয়ন বছরের পরিমাণ)</td><td>0%</td><td>&lt;0.01%</td><td>&lt;10</td></tr><tr><td>অ্যাঙ্কর জাগরণ যুগ</td><td>কয়েক হাজার বছর</td><td>1%→10%</td><td>0.01%→1%</td><td>10→30</td></tr><tr><td>সিম্বায়োসিস ব্যবস্থা প্রতিষ্ঠা কাল</td><td>কয়েক শতাব্দী</td><td>10%→40%</td><td>1%→10%</td><td>30→50</td></tr><tr><td>সিস্টেম খোলা এবং সক্রিয়করণ যুগ</td><td>কয়েক শতাব্দী</td><td>40%→70%</td><td>10%→30%</td><td>50→70</td></tr><tr><td>প্রথম মাত্রা-বৃদ্ধি যুগ</td><td>কয়েক দশক</td><td>70%→85%</td><td>30%→50%</td><td>70→80</td></tr><tr><td>সর্ব-জাতি গণতন্ত্র যুগ</td><td>কয়েক শতাব্দী</td><td>85%→95%</td><td>50%→70%</td><td>80→90</td></tr><tr><td>আন্তঃ-তল অনুসন্ধান যুগ</td><td>কয়েক হাজার বছর</td><td>95%→99%</td><td>70%→90%</td><td>90→95</td></tr><tr><td>আন্তঃগ্রহীয় সিম্বায়োসিস যুগ</td><td>চলমান</td><td>→100%</td><td>→100%</td><td>→100</td></tr></tbody></table><p>অ্যাঙ্কর কভারেজ রেট মানে অ্যাঙ্কর হার্ডওয়্যার মোতায়েন করা তলের উপ-অঞ্চলের অনুপাত; সাধকের অনুপাত মানে আনুষ্ঠানিক সাধনা ব্যবস্থা দ্বারা আচ্ছাদিত জীবের অনুপাত; সিম্বায়োসিস ডিগ্রি সূচক হলো সভ্যতার সিম্বায়োসিসের মাত্রা পরিমাপকারী একটি সমন্বিত সূচক, সর্বোচ্চ স্কোর 100।</p><h2 id="_4-যুগ-বিবর্তনের-অন্তর্নিহিত-যুক্তি" tabindex="-1">4. যুগ বিবর্তনের অন্তর্নিহিত যুক্তি <a class="header-anchor" href="#_4-যুগ-বিবর্তনের-অন্তর্নিহিত-যুক্তি" aria-label="Permalink to &quot;4. যুগ বিবর্তনের অন্তর্নিহিত যুক্তি&quot;">​</a></h2><p>হেংইয়ান-ঝৌর যুগ বিবর্তন রৈখিক সময়ের প্রবাহ নয়, বরং একটি সর্পিল ঊর্ধ্বগামী বিবর্তন প্রক্রিয়া। প্রতিটি যুগ আগের যুগের অবশিষ্ট মূল দ্বন্দ্ব সমাধান করার সাথে সাথে পরের যুগের বিকাশের শর্ত তৈরি করে:</p><ul><li>প্রি-অ্যাঙ্কর যুগের মূল দ্বন্দ্ব হলো লুণ্ঠন এবং সিম্বায়োসিসের দ্বন্দ্ব, এর চরমতা অ্যাঙ্কর জাগরণের অপরিহার্যতার দিকে পরিচালিত করে</li><li>অ্যাঙ্কর জাগরণ যুগ &quot;অ্যাঙ্কর বিদ্যমান কিনা&quot; সমস্যা সমাধান করে, কিন্তু &quot;অ্যাঙ্কর কার জন্য কাজ করে&quot; প্রশাসনিক চ্যালেঞ্জের মুখোমুখি হয়</li><li>সিম্বায়োসিস ব্যবস্থা প্রতিষ্ঠা কাল প্রশাসনিক গঠন সম্পন্ন করে, কিন্তু সাধনা সম্পদের একচেটিয়াতা এখনও জনগণের বিবর্তনকে বাধাগ্রস্ত করে</li><li>সিস্টেম খোলা এবং সক্রিয়করণ যুগ সাধনা একচেটিয়াতা ভেঙে দেয়, কিন্তু ব্যক্তিগত ক্ষমতার বৃদ্ধি নতুন নৈতিক এবং নিরাপত্তা চ্যালেঞ্জ নিয়ে আসে</li><li>প্রথম মাত্রা-বৃদ্ধি যুগ মাত্রা-বৃদ্ধির সম্ভাব্যতা যাচাই করে, কিন্তু একক তলের মাত্রা-বৃদ্ধি মহাবিশ্বের সামগ্রিক বিবর্তনকে চালাতে পারে না</li><li>সর্ব-জাতি গণতন্ত্র যুগ সভ্যতার ব্যবস্থা একীভূত করে, কিন্তু মহাবিশ্বে এখনও প্রচুর অপরিচিত তল এবং জাতি রয়েছে</li><li>আন্তঃ-তল অনুসন্ধান যুগ সভ্যতার সীমানা সম্প্রসারিত করে, কিন্তু বিচ্ছিন্ন তলগুলির আরও ঘনিষ্ঠ আন্তঃগ্রহীয় সংযোগ প্রয়োজন</li><li>আন্তঃগ্রহীয় সিম্বায়োসিস যুগ চূড়ান্তভাবে মহাবিশ্বের সামগ্রিক মাত্রা-বৃদ্ধির চূড়ান্ত লক্ষ্যের দিকে নির্দেশ করে</li></ul><h2 id="_5-বর্তমান-যুগের-অবস্থান" tabindex="-1">5. বর্তমান যুগের অবস্থান <a class="header-anchor" href="#_5-বর্তমান-যুগের-অবস্থান" aria-label="Permalink to &quot;5. বর্তমান যুগের অবস্থান&quot;">​</a></h2><p>হেংইয়ান-ঝৌর বর্তমান বিকাশের অবস্থা অনুযায়ী, সভ্যতা তৃতীয় যুগ (সিম্বায়োসিস ব্যবস্থা প্রতিষ্ঠা কাল) থেকে চতুর্থ যুগ (সিস্টেম খোলা এবং সক্রিয়করণ যুগ)ের সংক্রান্তিকালীন গুরুত্বপূর্ণ বিন্দুতে রয়েছে। সিম্বায়োসিস ব্যবস্থা ইতিমধ্যে প্রধান তলগুলিতে প্রয়োগ করা হয়েছে, তিনশট সিস্টেমের খোলার কাজ সম্পূর্ণরূপে এগিয়ে যাচ্ছে, 20% সক্রিয়করণ কৌশল বাস্তবায়ন পর্যায়ে প্রবেশ করেছে। নিয়ম প্রকৌশল স্তরের বেশ কিছু মূল প্রযুক্তি (গুণন ফলের অনুমান ইঞ্জিন, স্থান নিয়ম ডিভাইস, কপি মিরর সিস্টেম) পরীক্ষাগার থেকে বাল্ক উৎপাদনের দিকে এগিয়ে গেছে।</p><p>এই সংক্রান্তিকালীন সময়ের মূল কাজ হলো: তিনশট সিস্টেমের খোলা সত্যিই সব জীবের জন্য উপকারী হয় তা নিশ্চিত করা, সাথে সাথে 20% সক্রিয়করণ কৌশলের মাধ্যমে প্রথম দলের তলের সর্বোচ্চ শক্তিশালী ব্যক্তি প্রশিক্ষণ দেওয়া, প্রথম মাত্রা-বৃদ্ধির জন্য পর্যাপ্ত শক্তি এবং অভিজ্ঞতা জমা করা।</p><h2 id="উপসংহার" tabindex="-1">উপসংহার <a class="header-anchor" href="#উপসংহার" aria-label="Permalink to &quot;উপসংহার&quot;">​</a></h2><p>যুগ বিভাজন সারি সারণি হেংইয়ান-ঝৌর ঐতিহাসিক বিবর্তন বোঝার ম্যাক্রো কাঠামো। এটি মহাবিশ্বের দীর্ঘ ইতিহাসকে আটটি স্পষ্ট অন্তর্নিহিত যুক্তিযুক্ত যুগে সংকুচিত করে, প্রতিটি যুগ মহাবিশ্বের সামগ্রিক মাত্রা-বৃদ্ধির দিকে নির্দেশিত একটি প্রয়োজনীয় সিঁড়ি। পরবর্তী নথিগুলি প্রতিটি যুগ এবং এর গুরুত্বপূর্ণ ঘটনাগুলি বিস্তারিতভাবে ব্যাখ্যা করবে।</p><h2 id="সম্পর্কিত-নথি" tabindex="-1">সম্পর্কিত নথি <a class="header-anchor" href="#সম্পর্কিত-নথি" aria-label="Permalink to &quot;সম্পর্কিত নথি&quot;">​</a></h2><ul><li>71-প্রি-অ্যাঙ্কর যুগ</li><li>72-অ্যাঙ্কর জাগরণ যুগ</li><li>76-প্রথম মাত্রা-বৃদ্ধি মাইলফলক</li></ul>',22)])])}const c=d(l,[["render",i]]);export{u as __pageData,c as default};
